package com.fireplatform;

import com.fireplatform.simcard.SimCardConflicts;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import static org.assertj.core.api.Assertions.*;

class SimCardMigrationTest {
    record Db(String url,JdbcTemplate jdbc){ }
    Db db(String version){String url="jdbc:h2:mem:sim-migration-"+UUID.randomUUID()+";MODE=PostgreSQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";var config=Flyway.configure().dataSource(url,"sa","");config.target(version==null?"14":version);config.load().migrate();return new Db(url,new JdbcTemplate(new DriverManagerDataSource(url,"sa","")));}
    void latest(Db db){Flyway.configure().dataSource(db.url(),"sa","").target("14").load().migrate();}
    List<String> tables(JdbcTemplate j){return j.queryForList("SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY table_name",String.class);}
    Map<String,Object> facts(JdbcTemplate j,List<String> tables){var values=new TreeMap<String,Object>();for(String table:tables)if(!table.equals("flyway_schema_history"))values.put(table,j.queryForList("SELECT * FROM "+table));return values;}
    void tenant(JdbcTemplate j){j.update("INSERT INTO tenants(id,name) VALUES ('a','A'),('b','B')");}
    void user(JdbcTemplate j,String id,String type,boolean protectedUser){j.update("INSERT INTO app_users(id,username,display_name,user_type,tenant_id,password_hash,must_change_password,enabled,is_protected) VALUES (?,?,?,?,?,'Synthetic-Legacy-Hash',FALSE,TRUE,?)",id,id,id,type,type.equals("CUSTOMER")?"a":null,protectedUser);}
    String card(JdbcTemplate j,String tenant,String iccid){String id=UUID.randomUUID().toString();card(j,id,tenant,iccid);return id;}
    void card(JdbcTemplate j,String id,String tenant,String iccid){j.update("INSERT INTO sim_cards(id,tenant_id,iccid,carrier_name,installation_form,replaceability,management_party,fee_responsibility,reported_operator_status,expires_on,evidence_at,source_note,information_source,revision,recorded_at) VALUES (?,?,?,'','REMOVABLE','UNKNOWN','UNKNOWN','UNKNOWN','UNKNOWN',NULL,NULL,'','MANUAL',0,TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00')",id,tenant,iccid);}
    void change(JdbcTemplate j,String id,String tenant,long revision,String operation){j.update("INSERT INTO sim_card_changes(id,card_id,tenant_id,iccid,carrier_name,installation_form,replaceability,management_party,fee_responsibility,reported_operator_status,expires_on,evidence_at,source_note,information_source,revision,recorded_at,operation,actor_user_id) VALUES (?,?,?,'000Case','','REMOVABLE','UNKNOWN','UNKNOWN','UNKNOWN','UNKNOWN',NULL,NULL,'','MANUAL',?,TIMESTAMP WITH TIME ZONE '2026-01-02 03:04:05.123456+00:00',?,'actor')",UUID.randomUUID().toString(),id,tenant,revision,operation);}
    @Test void emptyLatestHasExactly48TablesAndNoCardHistoryOrPermissionSeeds(){var j=db(null).jdbc();assertThat(tables(j)).hasSize(48).contains("sim_cards","sim_card_changes");for(String table:List.of("sim_cards","sim_card_changes","user_permissions"))assertThat(j.queryForObject("SELECT COUNT(*) FROM "+table,Long.class)).isZero();assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_cards' ORDER BY ordinal_position",String.class)).containsExactly("id","tenant_id","iccid","carrier_name","installation_form","replaceability","management_party","fee_responsibility","reported_operator_status","expires_on","evidence_at","source_note","information_source","revision","recorded_at");assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name='sim_card_changes'",String.class)).hasSize(18).contains("card_id","id","operation","actor_user_id");}
    @Test void onlyTwoDatesAreNullableAndTimestampColumnsHaveMicrosecondPrecision(){var j=db(null).jdbc();for(String table:List.of("sim_cards","sim_card_changes")){assertThat(j.queryForList("SELECT column_name FROM information_schema.columns WHERE table_name=? AND is_nullable='YES' ORDER BY column_name",String.class,table)).containsExactly("evidence_at","expires_on");assertThat(j.queryForList("SELECT datetime_precision FROM information_schema.columns WHERE table_name=? AND column_name IN ('evidence_at','recorded_at')",Integer.class,table)).containsExactlyInAnyOrder(6,6);assertThat(j.queryForObject("SELECT data_type FROM information_schema.columns WHERE table_name=? AND column_name='expires_on'",String.class,table)).isEqualToIgnoringCase("date");}}
    @Test void v13UpgradePreservesEveryOldFactSchemaConstraintAndIndexExceptPreciselyTwoRootRights(){var db=db("13");var j=db.jdbc();tenant(j);for(String id:List.of("bootstrap-admin","other-protected","ordinary"))user(j,id,"PLATFORM",!id.equals("ordinary"));user(j,"customer","CUSTOMER",true);j.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin','device:read'),('ordinary','device:write')");j.update("INSERT INTO user_tenant_grants(user_id,tenant_id) VALUES ('bootstrap-admin','a')");j.update("INSERT INTO sessions(token_hash,user_id,audience,expires_at,revoked) VALUES ('legacy-session','bootstrap-admin','management',TIMESTAMP WITH TIME ZONE '2030-01-01 00:00:00+00:00',FALSE)");j.update("INSERT INTO devices(id,tenant_id,name,device_eui,model,address,physical_state) VALUES ('legacy-device','a','old','legacy-eui','old','old','FIRE')");j.update("INSERT INTO device_groups(id,tenant_id,name,description,revision) VALUES ('legacy-group','a','Old','Old',7)");j.update("INSERT INTO device_group_members(tenant_id,group_id,device_id) VALUES ('a','legacy-group','legacy-device')");var old=tables(j);assertThat(old).hasSize(46);var before=facts(j,old);var columns=j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public' ORDER BY table_name,ordinal_position");var constraints=j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public' ORDER BY table_name,constraint_name");var indexes=j.queryForList("SELECT * FROM information_schema.indexes WHERE table_schema='public' ORDER BY table_name,index_name");latest(db);assertThat(tables(j)).hasSize(48).containsAll(old);var after=facts(j,old);var permissions=j.queryForList("SELECT * FROM user_permissions WHERE permission NOT IN ('sim-cards:read','sim-cards:write')");after.put("user_permissions",permissions);assertThat(after).isEqualTo(before);assertThat(j.queryForList("SELECT permission FROM user_permissions WHERE user_id='bootstrap-admin' AND permission LIKE 'sim-cards:%' ORDER BY permission",String.class)).containsExactly("sim-cards:read","sim-cards:write");assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions WHERE user_id<>'bootstrap-admin' AND permission LIKE 'sim-cards:%'",Long.class)).isZero();String onlyOld=" AND table_name NOT IN ('sim_cards','sim_card_changes')";assertThat(j.queryForList("SELECT table_name,column_name,data_type,is_nullable FROM information_schema.columns WHERE table_schema='public'"+onlyOld+" ORDER BY table_name,ordinal_position")).isEqualTo(columns);assertThat(j.queryForList("SELECT table_name,constraint_name,constraint_type FROM information_schema.table_constraints WHERE table_schema='public'"+onlyOld+" ORDER BY table_name,constraint_name")).isEqualTo(constraints);assertThat(j.queryForList("SELECT * FROM information_schema.indexes WHERE table_schema='public'"+onlyOld+" ORDER BY table_name,index_name")).isEqualTo(indexes);}
    @Test void grantRequiresAllThreeExactRootConditionsAndNoOtherProtectedAccountQualifies(){for(String type:List.of("PLATFORM","CUSTOMER"))for(boolean protectedUser:List.of(false,true)){var db=db("13");var j=db.jdbc();tenant(j);user(j,"bootstrap-admin",type,protectedUser);user(j,"other-protected","PLATFORM",true);latest(db);assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions WHERE permission LIKE 'sim-cards:%'",Long.class)).isEqualTo(type.equals("PLATFORM")&&protectedUser?2L:0L);assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions WHERE user_id='other-protected'",Long.class)).isZero();}}
    @Test void existingOneOrBothRootRightsAreNotDuplicatedAndRepeatedLatestPreservesAllFacts(){for(boolean both:List.of(false,true)){var db=db("13");var j=db.jdbc();tenant(j);user(j,"bootstrap-admin","PLATFORM",true);j.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin','sim-cards:read')");if(both)j.update("INSERT INTO user_permissions(user_id,permission) VALUES ('bootstrap-admin','sim-cards:write')");latest(db);String id=card(j,"a","000Case");user(j,"actor","PLATFORM",false);change(j,id,"a",0,"CREATE");var before=facts(j,tables(j));latest(db);latest(db);assertThat(facts(j,tables(j))).isEqualTo(before);assertThat(j.queryForObject("SELECT COUNT(*) FROM user_permissions WHERE user_id='bootstrap-admin'",Long.class)).isEqualTo(2);assertThat(j.queryForObject("SELECT COUNT(*) FROM flyway_schema_history WHERE version='14' AND success=TRUE",Long.class)).isEqualTo(1);}}
    @Test void tenantScopedIccidIsCaseExactAndOnlyItsRealUniqueConstraintIsTranslated(){var j=db(null).jdbc();tenant(j);String id=card(j,"a","000Case");assertThatThrownBy(()->card(j,"a","000Case")).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(SimCardConflicts.iccid(e)).isTrue());card(j,"a","000case");card(j,"b","000Case");assertThatThrownBy(()->card(j,id,"a","other")).isInstanceOfSatisfying(DataAccessException.class,e->assertThat(SimCardConflicts.iccid(e)).isFalse());assertThat(j.queryForList("SELECT iccid FROM sim_cards WHERE tenant_id='a' ORDER BY iccid",String.class)).containsExactly("000Case","000case");}
    @Test void compositeCardTenantForeignKeyAndRevisionIdentityRejectCrossUnitOrDuplicateHistory(){var j=db(null).jdbc();tenant(j);user(j,"actor","PLATFORM",false);String id=card(j,"a","000Case");assertThatThrownBy(()->change(j,id,"b",0,"CREATE")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,UUID.randomUUID().toString(),"a",0,"CREATE")).isInstanceOf(DataAccessException.class);change(j,id,"a",0,"CREATE");assertThatThrownBy(()->change(j,id,"a",0,"CREATE")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,id,"a",1,"CREATE")).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->change(j,id,"a",0,"EDIT")).isInstanceOf(DataAccessException.class);change(j,id,"a",1,"EDIT");assertThat(j.queryForObject("SELECT COUNT(*) FROM sim_card_changes",Long.class)).isEqualTo(2);}
    @Test void enumSourceFormUuidAndSafeRevisionBoundsAreEnforcedByTheRealDatabase(){var j=db(null).jdbc();tenant(j);String id=card(j,"a","000Case");for(String sql:List.of("UPDATE sim_cards SET installation_form='EMBEDDED'","UPDATE sim_cards SET information_source='API'","UPDATE sim_cards SET replaceability='OTHER'","UPDATE sim_cards SET management_party='VENDOR'","UPDATE sim_cards SET fee_responsibility=NULL","UPDATE sim_cards SET reported_operator_status='TRUE'","UPDATE sim_cards SET source_note=NULL","UPDATE sim_cards SET revision=-1","UPDATE sim_cards SET revision=9007199254740992","UPDATE sim_cards SET iccid=''") )assertThatThrownBy(()->j.update(sql)).isInstanceOf(DataAccessException.class);assertThatThrownBy(()->card(j,"NOT-UUID","a","other")).isInstanceOf(DataAccessException.class);j.update("UPDATE sim_cards SET revision=9007199254740991 WHERE id=?",id);assertThat(j.queryForObject("SELECT revision FROM sim_cards WHERE id=?",Long.class,id)).isEqualTo(9007199254740991L);}
}
